# Kaggle CPU. Attach verified PINNS pose.npz or the earlier five-seed ZIP.
from pathlib import Path
import hashlib,base64,zlib,os,sys,subprocess,zipfile
rev="66fb39d2de3df280ac831a4b5a0c0f095f1a0779";repo=Path("/tmp/shortpose_ordered_geometry_"+rev[:12])
subprocess.run(["git","init","-q",str(repo)],check=True)
subprocess.run(["git","-C",str(repo),"fetch","-q","--depth=1","https://github.com/pjyyyds/Unstructured-ShortPose-Pred.git",rev],check=True)
subprocess.run(["git","-C",str(repo),"checkout","--detach","-q",rev],check=True)
sys.path.insert(0,str(repo))
from scripts.stage_pinns_metadata import stage_metadata
data=stage_metadata(Path("/tmp/pinns_ordered_geometry_metadata"))
pose_sha="b493a47536664ddb4fd66603c1bbf6b2c2e33f553520382027b3ae96b53447d0"
pose=next((p for p in sorted(Path("/kaggle/input").rglob("pose.npz")) if hashlib.sha256(p.read_bytes()).hexdigest()==pose_sha),None)
if pose is None:
    archives=[p for p in Path("/kaggle/input").rglob("shortpose_heldout_five_seeds.zip") if p.stat().st_size==42019120 and hashlib.sha256(p.read_bytes()).hexdigest()=="0bf2745ab2d5ddcf5f5fbb5d330e6c6cc800625cec301f4c7105d031bdb49d2d"]
    if not archives:raise ValueError("Missing verified five-seed or pose input")
    with zipfile.ZipFile(archives[0]) as z:raw=z.read("pose.npz")
    if hashlib.sha256(raw).hexdigest()!=pose_sha:raise ValueError("Wrong frozen observed poses")
    pose=Path("/tmp/pinns_ordered_geometry_pose.npz");pose.write_bytes(raw)
dst=Path("/tmp/pinns_ordered_geometry_driver");dst.mkdir(exist_ok=True)
def restore(name,h,compressed):
    data=zlib.decompress(base64.b64decode(compressed))
    if hashlib.sha256(data).hexdigest()!=h:raise ValueError("Changed "+name)
    (dst/name).write_bytes(data)
restore('geometry.py','d6fb6c8140993b2d2b8e020378301bda57497b8bfff4d43d7d2f2087028e32db','')
restore('run_geometry.py','cb867c184f7516379fa432aa9e1f2c8b562c90d0fc4e19324cbdf2c4c3026ee2','')
restore('plan.json','cd39946f8b9bab092e9517cd10d538e8f04eec8af5ea7d04fae80f858515b314','')
env={**os.environ,"PYTHONPATH":str(repo),"CUDA_VISIBLE_DEVICES":"","OPENBLAS_NUM_THREADS":"1","OMP_NUM_THREADS":"2","MKL_NUM_THREADS":"1"}
subprocess.run([sys.executable,"-u",str(dst/"run_geometry.py"),str(data),str(pose),str(dst/"plan.json"),"--mode","score"],env=env,cwd=repo,check=True)
